window.ScripturaLexicons.BDAG_PART_0097 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dorean-bdag\" data-source=\"BDAG\" data-search=\"δωρεάν dōreán advérbio gratuitamente; sem motivo; em vão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δωρεάν</td><td>advérbio</td><td>gratuitamente; sem motivo; em vão</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-doreomai-bdag\" data-source=\"BDAG\" data-search=\"δωρέομαι dōréomai verbo médio presentear; conceder; outorgar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δωρέομαι</td><td>verbo médio</td><td>presentear; conceder; outorgar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dorema-bdag\" data-source=\"BDAG\" data-search=\"δώρημα, ατος, τό dṓrēma substantivo neutro dom; presente; dádiva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δώρημα, ατος, τό</td><td>substantivo neutro</td><td>dom; presente; dádiva</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-doron-bdag\" data-source=\"BDAG\" data-search=\"δῶρον, ου, τό dôron substantivo neutro dom; presente; oferta sacrificial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δῶρον, ου, τό</td><td>substantivo neutro</td><td>dom; presente; oferta sacrificial</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-dorophoria-bdag\" data-source=\"BDAG\" data-search=\"δωροφορία, ας, ἡ dōrophoría substantivo feminino entrega de presentes; oferta de coleta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">δωροφορία, ας, ἡ</td><td>substantivo feminino</td><td>entrega de presentes; oferta de coleta</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epsilon-numeral-five-bdag\" data-source=\"BDAG\" data-search=\"ε´ eʹ sinal numeral cinco; quinto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ε´</td><td>sinal numeral</td><td>cinco; quinto</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ea-interjection-bdag\" data-source=\"BDAG\" data-search=\"ἔα éa partícula exclamativa ah!; ora!; deixe! BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔα</td><td>partícula exclamativa</td><td>ah!; ora!; deixe!</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ean-bdag\" data-source=\"BDAG\" data-search=\"ἐάν eán conjunção se; quando; sempre que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐάν</td><td>conjunção</td><td>se; quando; sempre que</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eanper-bdag\" data-source=\"BDAG\" data-search=\"ἐάνπερ eánper conjunção remissiva se de fato; contanto que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐάνπερ</td><td>conjunção remissiva</td><td>se de fato; contanto que</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-earinos-bdag\" data-source=\"BDAG\" data-search=\"ἐαρινός, ή, όν earinós adjetivo primaveril; da primavera BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐαρινός, ή, όν</td><td>adjetivo</td><td>primaveril; da primavera</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-heautou-bdag\" data-source=\"BDAG\" data-search=\"ἑαυτοῦ, ῆς, οῦ, pl. ἑαυτῶν heautoû pronome reflexivo de si mesmo; a si mesmo; reciprocamente; seu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑαυτοῦ, ῆς, οῦ, pl. ἑαυτῶν</td><td>pronome reflexivo</td><td>de si mesmo; a si mesmo; reciprocamente; seu</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eao-bdag\" data-source=\"BDAG\" data-search=\"ἐάω eáō verbo permitir; deixar; não impedir; abandonar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐάω</td><td>verbo</td><td>permitir; deixar; não impedir; abandonar</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hebdomas-bdag\" data-source=\"BDAG\" data-search=\"ἑβδομάς, άδος, ἡ hebdomás substantivo feminino semana; grupo de sete dias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑβδομάς, άδος, ἡ</td><td>substantivo feminino</td><td>semana; grupo de sete dias</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hebdomekonta-bdag\" data-source=\"BDAG\" data-search=\"ἑβδομήκοντα hebdomḗkonta numeral cardinal indeclinável setenta; setenta e dois; setenta e cinco; setenta e seis BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑβδομήκοντα</td><td>numeral cardinal indeclinável</td><td>setenta; setenta e dois; setenta e cinco; setenta e seis</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hebdomekontakis-bdag\" data-source=\"BDAG\" data-search=\"ἑβδομηκοντάκις hebdomēkontákis advérbio numeral setenta vezes; possivelmente setenta e sete vezes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑβδομηκοντάκις</td><td>advérbio numeral</td><td>setenta vezes; possivelmente setenta e sete vezes</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hebdomos-bdag\" data-source=\"BDAG\" data-search=\"ἕβδομος, η, ον hébdomos adjetivo numeral ordinal sétimo; sétima BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἕβδομος, η, ον</td><td>adjetivo numeral ordinal</td><td>sétimo; sétima</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ebeblekei-ebebleto-bdag\" data-source=\"BDAG\" data-search=\"ἐβεβλήκει, ἐβέβλητο ebeblḗkei, ebéblēto formas verbais remissivas ver βάλλω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐβεβλήκει, ἐβέβλητο</td><td>formas verbais remissivas</td><td>ver βάλλω</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eber-name-bdag\" data-source=\"BDAG\" data-search=\"Ἔβερ, ὁ Éber nome próprio masculino indeclinável Éber; filho de Selá BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἔβερ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Éber; filho de Selá</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eblethen-bdag\" data-source=\"BDAG\" data-search=\"ἐβλήθην eblḗthēn forma verbal remissiva ver βάλλω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐβλήθην</td><td>forma verbal remissiva</td><td>ver βάλλω</td><td><span class=\"source-pill\">BDAG</span></td></tr> <tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hebraikos-bdag\" data-source=\"BDAG\" data-search=\"Ἑβραϊκός, ή, όν Hebraïkós adjetivo hebraico; dos hebreus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἑβραϊκός, ή, όν</td><td>adjetivo</td><td>hebraico; dos hebreus</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-dorean-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δωρεάν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dōreán⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Acusativo de <span class=\"greek\">δωρεά</span>, empregado adverbialmente (desde Heródoto 5, 23 [<span class=\"greek\">δωρεήν</span>]; inscrições, papiros, LXX; PsSol 7:1; TestSol; Josefo).\n<p><strong>① Relativo àquilo que é dado gratuitamente, como presente, sem pagamento; gratuitamente, de graça.</strong> Além das referências em Nägeli 35s. e Poland 496, nota **, cf. GDI 2569, 4 [Delfos]; PSI 400, 16; 543, 19 e outras [ambos do século III a.C.]; 1401, 8; PTebt 5, 187; 250 [ambos do século II a.C.]; Gn 29:15; Êx 21:11, <span class=\"greek\">δωρεὰν ἄνευ ἀργυρίου</span> e outras passagens; Taciano 19, 1. <span class=\"greek\">δ. λαμβάνειν</span> (Josefo, Vi. 425), <span class=\"greek\">διδόναι</span> (Bell. 1, 274; Vi. 38), «receber ou dar gratuitamente», Mt 10:8 (cf. Sexto 242; acerca de um emissário que pagou suas próprias despesas de viagem, IPriene 108, 165); cf. Ap 21:6; 22:17. <span class=\"greek\">δ. εὐαγγελίσασθαι</span>, «anunciar o evangelho gratuitamente», 2Co 11:7. <span class=\"greek\">δικαιούμενοι δ.</span>, «justificados, feitos retos, como dádiva», Rm 3:24. <span class=\"greek\">οὐδὲ δ. ἄρτον ἐφάγομεν παρά τινος</span>, «nem comemos pão de alguém, ou recebido de alguém, sem pagar por ele», 2Ts 3:8.</p>\n<p><strong>② Relativo à ausência de culpa que contribua para determinado tratamento; imerecidamente, sem razão ou causa.</strong> <span class=\"greek\">ἐμίσησάν με δ.</span>, «odiaram-me sem motivo», Jo 15:25 (Sl 34:19; 68:5; PsSol 7:1; cf. Sl 118:161; 1Sm 19:5).</p>\n<p><strong>③ Relativo à ausência de finalidade; em vão, sem propósito.</strong> (Jó 1:9; Sl 34:7.) <span class=\"greek\">δ. ἀποθνῄσκειν</span>, «morrer em vão», Gl 2:21; ITr 10. — DELG, s.v. <span class=\"greek\">δίδωμι</span>. M-M., s.v. <span class=\"greek\">δωρεά</span>. TW.</p></div></section></article> <article id=\"entry-doreomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δωρέομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dōréomai⟧</span><span class=\"separator\">·</span><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐδωρησάμην</span>; perfeito <span class=\"greek\">δεδώρημαι</span>, particípio <span class=\"greek\">δεδωρημένος</span>; particípio neutro do aoristo passivo <span class=\"greek\">δωρηθέν</span> (a voz ativa é rara depois de Homero; a média está atestada desde Homero).\n<strong>Apresentar algo como presente ou conferir um benefício, provavelmente com certa sugestão de formalidade; presentear, conceder, outorgar.</strong> (Cf. Filóstrato, Vi. Soph. 2, 10, 7 [589], sob <span class=\"greek\">δῶρον</span>.) <span class=\"greek\">τινί τι</span>, «algo a alguém» (Ésquilo, Heródoto e outros; OGI 90, 31; 517, 7; POxy 1153, 15 [século I d.C.]; IDefixWünsch 4, 30; de Deus: Irineu 3, 18, 7 [Harv. II 100, 4]; Hipólito, Ref. 9, 30, 4; Dídimo, Gen. 66, 5; de Jesus: 81, 25); <span class=\"greek\">τὸ πτῶμα τῷ Ἰωσήφ</span>, «o corpo a José», Mc 15:45. <span class=\"greek\">τ. θείας δυνάμεως δεδωρημένης</span>, «visto que o poder divino concedeu», 2Pe 1:3. Por isso, no versículo 4, provavelmente voz média, não passiva (sobre um dom divino, Élio Aristides 13, p. 297 D.). — Dg 11:5. — DELG, s.v. <span class=\"greek\">δίδωμι</span> B. M-M. TW.</div></section></article> <article id=\"entry-dorema-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δώρημα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dṓrēma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ésquilo, Heródoto e outros; IG IV², 128, 53 [cerca de 280 a.C.], <span class=\"greek\">δ.</span> de Asclépio; Kaibel 1039, 13; Sir 34:18; Ezequiel Trágico 35 [em Eusébio, PE 9, 28], <span class=\"greek\">θεοῦ δ.</span>; Fílon, Somn. 1, 103, <span class=\"greek\">δ. παρὰ θεοῦ</span>.) <strong>Dom, dádiva, presente.</strong> <span class=\"greek\">δ. τέλειον</span>, «dom perfeito», Tg 1:17 (Fílon, Abr. 54, <span class=\"greek\">δ. τέλ.</span>; EpArist 276, <span class=\"greek\">θεοῦ δ. καλόν</span>; Josefo, Ant. 4, 318, <span class=\"greek\">δ. κάλλιστον</span>; PSI 29, 33, <span class=\"greek\">τἀγαθὰ δορήματα</span>). <span class=\"greek\">οὐχ ὡς δι’ ἑνὸς ἁμαρτήσαντος τὸ δ.</span>, «o dom (da graça) não é como os efeitos do pecado de um só homem», Rm 5:16. <span class=\"greek\">ἐκ τῶν ἰδίων δ.</span>, «dos dons que a própria pessoa recebeu», Hm 2:4. <span class=\"greek\">δ. τοῦ κυρίου</span>, Hs 2:7. — DELG, s.v. <span class=\"greek\">δίδωμι</span> B. M-M. TW.</div></section></article> <article id=\"entry-doron-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δῶρον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dôron⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Homero e seguintes; inscrições, papiros, LXX; En 100:12; Test12 Patr; JosAs 7:4; EpArist; Fílon; Josefo, C. Ap. 2, 207; Justino, D. 28, 4. Filóstrato, Vi. Soph. 2, 10, 7 [589], distingue <span class=\"greek\">δωρεά</span>, «concessão ou privilégio especial», de <span class=\"greek\">δῶρον</span>, «presente material».) <strong>Dom, presente.</strong>\n<p><strong>Presentes em geral:</strong> <span class=\"greek\">προσφέρειν δ.</span>, «trazer presentes» (cf. Gn 43:26; Dídimo, Gen. 228, 1, 10: <span class=\"greek\">αὐτὴν ὡς δῶρον</span>), Mt 2:11; cf. <span class=\"greek\">ἐξἐβαλον ἀπὸ τῆς πήρας αὐτῶν δῶρα χρυσόν …</span>, «tiraram da bolsa de viagem deles um presente de ouro», GJs 21:3. <span class=\"greek\">δῶρα πέμπειν ἀλλήλοις</span>, «enviar presentes uns aos outros», Ap 11:10.</p>\n<p><strong>Dons de Deus:</strong> (Homero e outros; Sotades Lyr. [século III a.C.] 9, 7, p. 242 Coll.; oráculo em Diodoro Sículo 8, 18, 1; Estrabão 16, 2, 35; Herm. Wr. 10, 9; EpArist 231; 272; Fílon, Congr. Erud. Gr. 38; Dídimo, Gen. 161, 2), 1Cl 35:1. Com <span class=\"greek\">ἐπαγγελίαι</span>, Hv 3, 2, 1. <span class=\"greek\">καὶ τοῦτο οὐκ ἐξ ὑμῶν, θεοῦ τὸ δ.</span>, «e isso não foi realizado por vossas próprias forças; é dom de Deus», Ef 2:8.</p>\n<p><strong>Dons e ofertas sacrificiais:</strong> (Platão, Euthphr. 15a; SIG 1141; 1154, <span class=\"greek\">Διὶ δ.</span>; OGI 407, 4; Justino, D. 28, 4), Hb 11:4; 1Cl 4:2 (Gn 4:4); GJs 7:1. <span class=\"greek\">εἰς τὰ δ. βάλλειν</span>, «lançar entre as ofertas», isto é, aquelas já depositadas no recipiente de oferendas, Lc 21:4; cf. v. 1. <span class=\"greek\">προσφέρειν τὸ δ.</span>, «trazer a própria oferta» (Lv 1:2, 14; 2:1, 4 e frequentemente; TestIss 5:3), Mt 5:23s.; 8:4; Hb 5:1; 8:3s.; 9:9 (com <span class=\"greek\">θυσίαι</span>, como em Lv 21:6; cf. EpArist 234); GJs 1:1s.; 5:1; cf. 1Cl 44:4. <span class=\"greek\">ἀφιέναι τὸ δ.</span>, «deixar a própria oferta», Mt 5:24. <span class=\"greek\">δ.</span> como tradução de <span class=\"hebrew\">קָרְבָּן</span> (Josefo, Ant. 4, 73; C. Ap. 1, 167), Mc 7:11; cf. Mt 15:5. <span class=\"greek\">ἁγιάζειν τὸ δ.</span>, «santificar a oferta», Mt 23:19; cf. v. 18. A respeito de uma criança consagrada ao serviço do templo: <span class=\"greek\">προσάξω (αὐτὸ) δῶρον Κυρίῳ τῷ θεῷ μου</span>, GJs 4:1 (cf. 1Sm 1:11).</p>\n<p>Variante textual para <span class=\"greek\">λόγον</span>, Qua (1). — DELG, s.v. <span class=\"greek\">δίδωμι</span> B. M-M. TW.</p></div></section></article> <article id=\"entry-dorophoria-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δωροφορία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦dōrophoría⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(De <span class=\"greek\">δῶρον</span> + <span class=\"greek\">φέρω</span>, por intermédio de <span class=\"greek\">-φορος</span>.) <strong>Entrega de presentes</strong> (Alcífron 1, 6; Pólux 4, 47; B-D-F §119, 1); <strong>entrega de uma dádiva proveniente de uma coleta</strong>, Rm 15:31, variante textual para <span class=\"greek\">διακονία</span>. — Ver DELG, s.v. <span class=\"greek\">φέρω</span>. M-M.</div></section></article> <article id=\"entry-epsilon-numeral-five-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ε´</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eʹ⟧</span><span class=\"separator\">·</span><span>sinal numeral</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Sinal numeral equivalente a <strong>5</strong> (<span class=\"greek\">πέντε</span>) ou <strong>quinto</strong> (<span class=\"greek\">πέμπτη</span>); At 19:9, códice D. Em títulos: Hv 5; m 5; Hs 5 (Apolônio, Paradox. 46: <span class=\"greek\">Θεόφραστος ἐν τῇ ε´ τῶν φυτικῶν αἰτιῶν φησίν</span>; frequentemente em papiros, p.ex., PWisc II, 80, 15 e outros).</div></section></article> <article id=\"entry-ea-interjection-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éa⟧</span><span class=\"separator\">·</span><span>partícula exclamativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Ésquilo e outros poetas áticos; rara em prosa: Platão, Prot. 314d; Epicteto 2, 24, 22; 3, 20, 5; Jó 15:16; 25:6.) <strong>Partícula exclamativa que exprime surpresa ou desagrado; ah!, ora!</strong>, Mc 1:24, variante textual; Lc 4:34. Parece provável alguma ligação com <span class=\"greek\">ἔα</span>, imperativo de <span class=\"greek\">ἐάω</span>, «deixa em paz!», em 1Cl; e possível em Mc e Lc (cf. a Vulgata e o sentido da NRSV em Lc 4:34). Ver <span class=\"greek\">ἐάω</span> 2.</div></section></article> <article id=\"entry-ean-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐάν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eán⟧</span><span class=\"separator\">·</span><span>conjunção</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Homero e seguintes.) Introduz fundamentalmente uma situação na qual, dado X, seguir-se-á Y (B-D-F §§31, 1; 107; 371, 4; 372, 1a; 373; Mlt. e Rob., índices).\n<p><strong>① Como conjunção, marcador de condição, deixando em aberto a probabilidade de realização da ação expressa no verbo e, por isso, particularmente adequado a afirmações generalizantes; «se».</strong> Apenas raramente [1Co 6:4; 11:14, como, p.ex., Luciano, Vit. Auct. 11, <span class=\"greek\">καὶ ἰδιώτης γὰρ ἐὰν ᾖς</span>] aparece em posição que não seja o início da oração subordinada.</p>\n<p><strong>ⓐ Com subjuntivo, indicando aquilo que, de determinado ponto de vista no presente, se espera que ocorra sob certas circunstâncias, gerais ou particulares</strong> (B-D-F §371, 4; Mlt-Turner 114s.).</p>\n<p><strong>α. Com subjuntivo presente e presente na apódose:</strong> <span class=\"greek\">ἐὰν θέλῃς δύνασαί με καθαρίσαι</span>, Mt 8:2; Mc 1:40; Lc 5:12. <span class=\"greek\">ἐὰν ἀγαθοποιῆτε, ποία ὑμῖν χάρις ἐστίν;</span>, Lc 6:33. <span class=\"greek\">ἐὰν μαρτυρῶ, ἡ μαρτυρία μου οὐκ ἔστιν ἀληθής</span>, Jo 5:31 (mas ver 1bβ abaixo); cf. 8:16; 15:14. <span class=\"greek\">περιτομὴ ὠφελεῖ ἐὰν νόμον πράσσῃς</span>, Rm 2:25; cf. 13:4; 14:8; 1Co 13:1ss. e outras passagens. Com subjuntivo presente e aoristo na apódose: <span class=\"greek\">ἐὰν ὁ ποῦς σου σκανδαλίζῃ σε, ἀπόκοψον</span>, Mc 9:45; cf. v. 47. Com futuro na apódose: <span class=\"greek\">ἐὰν ᾖ … ἐπαναπαήσεται</span>, Lc 10:6; <span class=\"greek\">ἐὰν ὁδηγῇ, πεσοῦνται</span>, Mt 15:14.</p>\n<p><strong>β. Principalmente com subjuntivo aoristo e presente na apódose:</strong> <span class=\"greek\">ἐὰν ἀγαπήσητε, τίνα μισθὸν ἔχετε;</span>, Mt 5:46; cf. v. 47; 18:15ss. <span class=\"greek\">ἐὰν μερισθῇ, οὐ δύναται σταθῆναι</span>, Mc 3:24. <span class=\"greek\">ἐὰν γαμήσῃ, μοιχᾶται</span>, Mc 10:12. <span class=\"greek\">ἐὰν ἀπολέσῃ, οὐχὶ ἅπτει;</span>, Lc 15:8. <span class=\"greek\">ἐὰν μείνητε, μαθηταί μού ἐστε</span>, Jo 8:31; cf. 19:12. <span class=\"greek\">ἐὰν χωρισθῇ, μενέτω</span>, 1Co 7:11; cf. v. 39. <span class=\"greek\">ἐὰν φάγωμεν, περισσεύομεν</span>, 1Co 8:8. Com subjuntivo aoristo e aoristo na apódose: <span class=\"greek\">ἐὰν εἴπωσιν, μὴ ἐξέλθητε</span>, Mt 24:26. <span class=\"greek\">ἐὰν ἁμάρτῃ, ἐπιτίμησον … ἐὰν μετανοήσῃ, ἄφες</span>, Lc 17:3; <span class=\"greek\">ἐὰν εἴπω, οὐ μὴ πιστεύσητε</span>, Lc 22:67; cf. v. 68. Com subjuntivo aoristo e futuro na apódose (cf. Esopo, Fab. 408b H.//250 I, H-H.): <span class=\"greek\">ἐὰν ἀφῆτε, ἀφήσει καὶ ὑμῖν</span>, Mt 6:14. <span class=\"greek\">ἐὰν ἅψωμαι, σωθήσομαι</span>, Mt 9:21. <span class=\"greek\">ἐὰν ἐμπέσῃ, οὐχὶ κρατήσει;</span>, Mt 12:11; cf. 24:48, 50; 28:14; Mc 8:3; Lc 4:7; 14:34; Jo 15:10 e outras passagens (com optativo aoristo na apódose: Justino, A II, 15, 2).</p>\n<p><strong>γ. Com subjuntivo presente e aoristo simultaneamente:</strong> <span class=\"greek\">ἐὰν δὲ καὶ ἀθλῇ τις</span>, «mesmo que alguém seja atleta por profissão», <span class=\"greek\">οὐ στεφανοῦται, ἐὰν μὴ νομίμως ἀθλήσῃ</span>, «não recebe a coroa se não competir conforme as regras» (ação isolada ou repetida), 2Tm 2:5. Em 1Co 14:23, <span class=\"greek\">ἐὰν συνέλθῃ</span> (ação anterior) e <span class=\"greek\">λαλῶσιν</span> (ação reiterada e duradoura), depois <span class=\"greek\">εἰσέλθωσιν δέ</span> (uma única vez); cf. v. 24. <span class=\"greek\">ἐὰν ἔχητε πίστιν καὶ μὴ διακριθῆτε</span>, Mt 21:21.</p>\n<p><strong>ⓑ Com indicativo</strong> (exemplos em Dssm., NB 29s. [BS 201s.]; B-D-F §372, 1a; Mlt. 168; Mlt-Turner 115s.; Rdm.² 200; Rob. 1009s.).</p>\n<p><strong>α. Com indicativo futuro, no mesmo sentido</strong> (CIG II, 2485, <span class=\"greek\">ἐὰν θελήσει</span>; papiros; TestReub 4:11; TestJob 4:4, <span class=\"greek\">ἐὰν ἐπιχειρήσεις</span>; B-D-F §373, 2): <span class=\"greek\">ἐὰν οὗτοι σιωπήσουσιν, οἱ λίθοι κράξουσιν</span>, Lc 19:40 (variantes <span class=\"greek\">σιγήσουσιν</span>, <span class=\"greek\">σιωπήσωσιν</span>). <span class=\"greek\">ἐὰν μή τις ὁδηγήσει με</span>, At 8:31 (variante <span class=\"greek\">ὁδηγήσῃ</span>). <span class=\"greek\">ἐὰν ἡμᾶς μιμήσεται … οὐκ ἔτι ἐσμέν</span>, IMg 10:1; <span class=\"greek\">ἐὰν μετανοήσουσιν</span>, Hv 1, 3, 2; <span class=\"greek\">ἐὰν προσθήσω</span>, m 4, 3, 7; <span class=\"greek\">ἐὰν ἔσῃ</span>, m 5, 1, 2.</p>\n<p><strong>β. Com indicativo presente</strong> (Ocel[o], século II a.C., 5; Cirilo de Citópolis, p. 145, 5, <span class=\"greek\">ἐὰν ἔστιν</span>; CIG II, 2485, <span class=\"greek\">ἐὰν βούλονται</span>; TestJud 15:2, variante; Justino, D. 47, 1 e 3; 67, 2): <span class=\"greek\">ἐὰν στήκετε ἐν κυρίῳ</span>, 1Ts 3:8 (variante <span class=\"greek\">στήκητε</span>); IMg 5:2; Hv 3, 12, 3; <span class=\"greek\">ἐὰν οἴδαμεν</span>, 1Jo 5:15 (sobre esta ocorrência e Jo 5:31 [ver 1aα acima], ver B-D-F §372, 1 = B-D-R §373, 3, nota 12); <span class=\"greek\">ἐὰν πάσχομεν</span>, Pol. 8:2.</p>\n<p><strong>γ. Com indicativo aoristo.</strong> Em Mt 15:5 = Mc 7:11, N²⁴ acentua <span class=\"greek\">ὠφελήθης</span> em lugar de <span class=\"greek\">ὠφεληθῇς</span> (N.), fornecendo exemplo de <span class=\"greek\">ἐάν</span> com indicativo aoristo, construção fortemente apoiada em B-D-F §360, 1. É rara, mas aparece ocasionalmente na <span class=\"greek\">κοινή</span> tardia (Rob. 1009).</p>\n<p><strong>ⓒ Com outras partículas:</strong></p>\n<p><strong>α.</strong> <span class=\"greek\">ἐὰν καί</span>, «mesmo se», Gl 6:1; igualmente <span class=\"greek\">ἐὰν δὲ καί</span> (POxy 472 II, 7), «mas se», 1Co 7:11, 28; 2Tm 2:5. <span class=\"greek\">ἐὰν δὲ καὶ παρακούσῃ</span>, «mas se a pessoa se recusar a ouvir», Mt 18:17.</p>\n<p><strong>β.</strong> <span class=\"greek\">ἐὰν μή</span>, «se não, a menos que»; com subjuntivo presente: <span class=\"greek\">ἐὰν δὲ μὴ ᾖ ἀξία</span>, Mt 10:13; cf. Lc 13:3; Jo 3:2s., 5, 27. Na maioria das vezes, com subjuntivo aoristo: <span class=\"greek\">ἐὰν μὴ περισσεύσῃ</span>, Mt 5:20; 6:15; 12:29; 18:3; 21:21; Mc 3:27; 4:22 (ver K. Beyer, <em>Semitische Syntax im NT</em>, 1962, 131); Jo 4:48; 6:44; 7:51; Rm 10:15; 1Co 9:16; 14:6. «A menos que, sem»: <span class=\"greek\">ἐὰν μὴ αὐτὸ πίω</span>, Mt 26:42. Com futuro: <span class=\"greek\">ἐὰν μὴ μετανοήσουσιν</span>, Ap 2:22.</p>\n<p><strong>γ.</strong> <span class=\"greek\">ἐάνπερ</span>, «se de fato, contanto que, supondo que», referindo-se «ainda a outra condição (fato)» (B-D-F §454, 2), com subjuntivo presente (Platão, Ap. 12, 25b; Xenofonte, Cyr. 4, 6, 8; PFay 124, 9), Hb 6:3; IRo 1:1; e com aoristo (Plutarco, Lyc. 40 [3, 2]; BGU 1141, 30), IRo 1:2; IPol 7:1; Hb 3:6, 14 (variante <span class=\"greek\">ἐάν</span>).</p>\n<p><strong>δ.</strong> <span class=\"greek\">ἐάν τε … ἐάν τε</span>, «quer … quer» (Xenofonte, Cyr. 3, 3, 17; Mem. 2, 4, 6; Élio Aristides 53, p. 622 D.; Máximo de Tiro 1, 9a), Rm 14:8 (sobre a ocorrência isolada de <span class=\"greek\">ἐάν τε</span> em 2Co 10:8, ver Rad² 5).</p>\n<p><strong>ε.</strong> <span class=\"greek\">ἐὰν οὖν</span>, ver <span class=\"greek\">οὖν</span> 2d. Ver também <span class=\"greek\">κἄν</span>.</p>\n<p><strong>② Como conjunção, marcador da perspectiva de uma ação num ponto do tempo coordenado com outro ponto temporal.</strong> Desse modo, por vezes o sentido de <span class=\"greek\">ἐάν</span> aproxima-se bastante daquele de <span class=\"greek\">ὅταν</span>, <strong>«sempre que, quando»</strong> (Is 24:13; Am 7:2; Tb 6:17 BA, <span class=\"greek\">ἐὰν εἰσέλθῃς</span>, cf. S, <span class=\"greek\">ὅταν εἰς</span>; 4:3 BA, cf. v. 4), 1Jo 2:28 (variante <span class=\"greek\">ὅταν</span>); Jo 12:32 (variante <span class=\"greek\">ὅταν</span>); 14:3; Hb 3:7 (Sl 94:7).</p>\n<p><strong>③ Marcador da possibilidade de um número indeterminado de ocorrências de um mesmo evento.</strong> Muito frequentemente no lugar de <span class=\"greek\">ἄν</span> (ver esse verbete) após relativos (assim Lísias 24, 18 Thalh., variante conforme os manuscritos; papiros desde 246 a.C. [Mayser 152s.]; LXX [Thackeray 67]; Melitão, P. 35, 236 [B], <span class=\"greek\">πάντα ὅσα ἐὰν γείνηται</span>. — Dssm., NB 29s. [BS 201s.]; Mlt. 42s.; B-D-F §107; Rdm.² 203s.; Crönert 130s.; Rob. 190s.; segundo Rydbeck, mais frequente nos séculos I–II d.C., especialmente em textos de linguagem corrente). <span class=\"greek\">ὸ̔ς ἐάν = ὸ̔ς ἄν</span> (PTebt 107, 8 [século II a.C.]; Gn 15:14), Mt 5:19, 32; 1Cl 32:1. <span class=\"greek\">ὅπου ἐάν = ὅπου ἄν</span>, Mt 8:19. <span class=\"greek\">ὁσάκις ἐάν = ὁσάκις ἄν</span>, Ap 11:6. <span class=\"greek\">οὗ ἐάν = οὗ ἄν</span>, 1Co 16:6. — Rydbeck 119–44. DELG. M-M.</p></div></section></article> <article id=\"entry-eanper-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐάνπερ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eánper⟧</span><span class=\"separator\">·</span><span>conjunção remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Ver <span class=\"greek\">ἐάν</span> 1cγ. — M-M.</div></section></article> <article id=\"entry-earinos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐαρινός, ή, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦earinós⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Homero [variante <span class=\"greek\">εἰαρ-</span>] e outros; Diodoro Sículo 5, 41, 6; inscrições, papiros; Fílon, Mos. 2, 186 e outras passagens.) <strong>Relativo à estação entre o inverno e o verão; da primavera, primaveril.</strong> <span class=\"greek\">καιροὶ ἐ.</span>, «estações primaveris» (como em Fílon, Op. M. 153, <span class=\"greek\">ἐαριναὶ ὧραι</span>), 1Cl 20:9. — DELG, s.v. <span class=\"greek\">ἔαρ</span> 2.</div></section></article> <article id=\"entry-heautou-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑαυτοῦ, ῆς, οῦ, pl. ἑαυτῶν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦heautoû⟧</span><span class=\"separator\">·</span><span>pronome reflexivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Pronome reflexivo (Homero e seguintes; JosAs 7:6 [frequentemente no códice A; 3:2 <span class=\"greek\">αὐτοῦ</span>]). Os editores substituem de maneiras diversas as formas contraídas <span class=\"greek\">αὑτοῦ</span> e <span class=\"greek\">αὑτῶν</span> de manuscritos posteriores pelas formas não contraídas ou por <span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">αὐτῶν</span>; comparem-se, por exemplo, os textos de Mc 9:16; Lc 23:12; Jo 2:24; 20:10; At 14:17; Rm 1:24; Ef 2:15; Hb 5:3; 1Jo 5:10; Ap 8:6; 18:7 em GNT¹–³ com GNT⁴; ver também o tratamento dessas mesmas passagens por Merk. Compare-se a evidência manuscrita de Fp 3:21 em GNT¹–³ com sua ausência em GNT⁴ (W-S. §22³, 16; B-D-F §64, 1; Mayser 305; I²/2, 65; Rob. 226; Mlt-Turner 190; M-M., s.v. <span class=\"greek\">αὑτοῦ</span>; R. Borger, TRu 52, 1988, 17–19).\n<p><strong>① Indicador da identidade com a pessoa que fala ou age; «si mesmo».</strong></p>\n<p><strong>ⓐ Para a terceira pessoa do singular e plural.</strong> <span class=\"greek\">ταπεινοῦν ἑαυτόν</span>, «humilhar-se», Mt 18:4; 23:12. Em oposição, <span class=\"greek\">ὑψοῦν ἑ.</span>, «exaltar-se», Mt 23:12; <span class=\"greek\">δοξάζειν ἑ.</span>, «glorificar-se», Ap 18:7, variante textual. <span class=\"greek\">ἀπαρνεῖσθαι ἑ.</span>, «negar-se a si mesmo», Mt 16:24; Mc 8:34 (Melitão, P. 26, 181); <span class=\"greek\">ἀμάρτυρον ἑ. ἀφεῖναι</span>, «deixar a si mesmo sem testemunho», At 14:17, variante; <span class=\"greek\">ἑτοιμάζειν ἑ.</span>, «preparar-se», Ap 8:6, variante; <span class=\"greek\">εὐνουχίζειν ἑ.</span>, «fazer de si mesmo eunuco», Mt 19:12; <span class=\"greek\">σῴζειν ἑ.</span>, «salvar-se» (Josefo, Ant. 10, 137), Mt 27:42; <span class=\"greek\">κατακόπτειν ἑ.</span>, «ferir-se», Mc 5:5; <span class=\"greek\">πιστεύειν ἑαυτόν τινι</span>, Jo 2:24, variante, e outros usos; <span class=\"greek\">ἀγοράζειν τι ἑαυτῷ</span>, «comprar algo para si mesmo», Mt 14:15; Mc 6:36; <span class=\"greek\">θησαυρίζων ἑαυτῷ</span>, «acumulando riquezas para si», Lc 12:21; <span class=\"greek\">ὑποτάσσειν ἑ.</span>, Fp 3:21, variante. Com a voz média (cf. Xenofonte, Mem. 1, 6, 13, <span class=\"greek\">ποιεῖσθαι ἑαυτῷ φίλον</span>; Sir 37:8): <span class=\"greek\">διεμερίσαντο ἑαυτοῖς</span>, «dividiram entre si», Jo 19:24 (Sl 21:19). — O dativo simples também pode realçar o sujeito como agente (Heródoto 1, 32; Estrabão 2, 1, 35; POxy 2351, 49; Sl 26:12; SSol 1:8): <span class=\"greek\">βαστάζων ἑαυτῷ τὸν σταυρόν</span>, «carregando a cruz sem auxílio», Jo 19:17; <span class=\"greek\">ἑαυτοῖς κρίμα λήμψονται</span>, «eles mesmos serão responsáveis pela condenação que receberão», Rm 13:2; <span class=\"greek\">οὐκ ἐπαινοῦμεν τοὺς προσιόντας ἑαυτοῖς</span>, «não elogiamos os que tomam a iniciativa de se promover», MPol 4; cf. <span class=\"greek\">στρῶσον σεαυτῷ</span>, «arruma tua própria cama», At 9:34. — Rydbeck 51–61. Usado especialmente com preposições:</p>\n<p><strong>α. <span class=\"greek\">ἀφ’ ἑαυτοῦ</span></strong> (<span class=\"greek\">ἀπό</span> 5eα; TestAbr A 19, p. 101, 6 [Stone p. 50]; Justino, A I, 43, 8, <span class=\"greek\">ἀφ’ ἑαυτοῦ ἑλόμενος τὸ ἀγαθόν</span>; Taciano 17, 4, <span class=\"greek\">ἐχθρὸν ἀμυνεῖται</span>): <span class=\"greek\">ποιεῖν τι</span>, «fazer algo por iniciativa própria», Jo 5:19. <span class=\"greek\">λαλεῖν</span>, «falar por sua própria autoridade» (Diodoro Sículo 12, 66, 2, <span class=\"greek\">ἐκήρυξέ τις ἀφ’ ἑαυτοῦ</span>, isto é, sem ordens de uma autoridade superior), Jo 7:18; 16:13. <span class=\"greek\">λέγειν</span>, Jo 11:51; 18:34, variante (Marco Aurélio 11, 19, <span class=\"greek\">τοῦτο οὐκ ἀπὸ σαυτοῦ μέλλεις λέγειν</span>). <span class=\"greek\">καρπὸν φέρειν</span>, «dar fruto por si mesmo», Jo 15:4. <span class=\"greek\">ἱκανὸν εἶναι</span>, «ser competente por si mesmo», 2Co 3:5 (<span class=\"greek\">ἀφ’ ἑαυτῶν</span> alternando com <span class=\"greek\">ἐξ ἑαυτῶν</span>; ver também 1aδ). <span class=\"greek\">γινώσκειν</span>, «saber por si mesmo», Lc 21:30. <span class=\"greek\">κρίνειν</span>, «julgar por si mesmo», Lc 12:57 (<span class=\"greek\">ἐξετάζειν</span>, Ath. 18, 1).</p>\n<p><strong>β. <span class=\"greek\">δι’ ἑαυτοῦ</span></strong> (POxy 273, 21; PTebt 72, 197; TestJob 16:4): <span class=\"greek\">κοινὸς δι’ ἑαυτοῦ</span>, «impuro em si mesmo», Rm 14:14 (EpJer 26; Justino, A I, 54, 8; A II, 10, 8; D. 56, 1).</p>\n<p><strong>γ. <span class=\"greek\">ἐν ἑαυτῷ</span></strong>, «a si mesmo, em si mesmo»: <span class=\"greek\">εὐπαρεπέστατον ἦν ἐν αὑτῷ τὸ ὄρος</span>, Hs 9, 1, 10; Jo 13:32, variante; Rm 1:24, variante; Ef 2:15, variante. De outro modo, principalmente com verbos de falar, em oposição à expressão audível; ver <span class=\"greek\">διαλογίζομαι</span> 1, <span class=\"greek\">εἶπον</span> 6, <span class=\"greek\">λέγω</span> 1bζ. Ainda <span class=\"greek\">ἔχειν τι ἐν ἑαυτῷ</span>, «ter algo em si mesmo» (cf. Jdth 10:19; Josefo, Ant. 8, 171; Justino, D. 8, 2; Ath. 10, 2), Jo 5:26, 42; 6:53; 17:13; 2Co 1:9. Em geral, acerca do que ocorre na consciência interior: <span class=\"greek\">διαπορεῖν</span>, At 10:17. Especialmente <span class=\"greek\">γίνεσθαι ἐν ἑαυτῷ</span>, «voltar a si, recobrar os sentidos», At 12:11 (Xenofonte, An. 1, 5, 17, <span class=\"greek\">ὁ Κλέαρχος ἐν ἑαυτῷ ἐγένετο</span>; Políbio 1, 49, 8; Cáriton 3, 9, 11, <span class=\"greek\">ἐν ἑαυτῷ γενόμενος</span>). Também:</p>\n<p><strong>δ. <span class=\"greek\">ἐξ ἑαυτῶν</span></strong> (Sófocles, El. 343, <span class=\"greek\">ἐκ σαυτῆς</span>; Teofrasto, frag. 96 [em Ps.-Demétrio 222], <span class=\"greek\">ἐξ αὑτοῦ</span>), «por nossas próprias forças», 2Co 3:5.</p>\n<p><strong>ε. <span class=\"greek\">εἰς ἑαυτὸν ἔρχεσθαι</span></strong>, «voltar a si, cair em si», Lc 15:17 (Diodoro Sículo 13, 95, 2; Epicteto 3, 1, 15; GrBar 17:3).</p>\n<p><strong>ζ. <span class=\"greek\">καθ’ ἑαυτόν</span></strong>, «por si mesmo, sozinho» (Xenofonte, Mem. 3, 5, 4; Plutarco, Anton. 940 [54, 1 e 2]; 2Mc 13:13; Justino, D. 4, 5; 74:2; Ath. 15, 2 e outros): <span class=\"greek\">μένειν</span>, «viver sozinho (numa casa particular)», At 28:16. <span class=\"greek\">πίστις νεκρά ἐστιν καθ’ ἑαυτήν</span>, «a fé, quando permanece por si mesma, está morta», Tg 2:17 (Diógenes Laércio 1, 64, de uma carta de Sólon: religião e legisladores nada podem fazer <span class=\"greek\">καθ’ ἑαυτά</span>, isto é, se dependerem apenas de si mesmos). <span class=\"greek\">βασιλεία μερισθεῖσα καθ’ ἑαυτῆς</span>, «um reino dividido contra si mesmo», Mt 12:25. <span class=\"greek\">μεθ’ ἑαυτοῦ, μεθ’ ἑαυτῶν</span>, «consigo mesmo, consigo mesmos» (cf. 1Sm 9:3; 24:3, <span class=\"greek\">ἔλαβεν μεθ’ ἑ.</span>), Mt 12:45; 25:3.</p>\n<p><strong>η. <span class=\"greek\">παρ’ ἑαυτῷ τιθέναι τι</span></strong>, «pôr algo de parte», 1Co 16:2 (Xenofonte, Mem. 3, 13, 3; cf. Josefo, Ant. 9, 68, <span class=\"greek\">οἴκαδε παρ’ αὑτῷ</span>; Taciano 7, 2, <span class=\"greek\">λόγου δύναμις ἔχουσα παρ’ ἑαυτῇ τὸ προγνωστικόν</span>, «tem em si mesmo»).</p>\n<p><strong>θ. <span class=\"greek\">περὶ ἑ. προσφέρειν</span></strong>, «fazer uma oferta por si mesmo», Hb 5:3. <span class=\"greek\">τὰ περι ἑαυτοῦ</span>, «as passagens que falam a seu respeito», Lc 24:27.</p>\n<p><strong>ι. <span class=\"greek\">πρὸς ἑαυτὸν προσεύχεσθαι</span></strong>, «orar consigo mesmo» (= em silêncio), Lc 18:11 (cf. Aristeneto, Ep. 1, 6; 2Mc 11:13; Josefo, Ant. 11, 210; Vi. Aesopi G 9 P., <span class=\"greek\">πρὸς ἑαυτὸν εἶπεν</span>; 38; Justino, D. 62, 2, <span class=\"greek\">πρὸς ἑαυτὸν ἔλεγεν ὁ θεός … πρὸς ἑαυτοὺς λέγομεν</span>). <span class=\"greek\">ἀπῆλθεν πρὸς ἑαυτόν, θαυμάζων τὸ γέγονος</span>, «(Pedro) foi para casa, admirando-se durante todo o tempo do que havia acontecido», Lc 24:12 (F. Neirynck, ETL 54, 1978, 104–18). <span class=\"greek\">ἀπέρχεσθαι πρὸς ἑαυτούς</span>, «ir para casa», Jo 20:10, variante (para <span class=\"greek\">αὐτούς</span>, cf. Políbio 5, 93, 1; Nm 24:25; Josefo, Ant. 8, 124; ver M. Black, <em>An Aramaic Approach</em>³, 1967, 102s.). Lc 23:12, variante.</p>\n<p><strong>ⓑ Para a primeira e a segunda pessoa do plural</strong> (em geral, no grego helenístico; ver F. Kälker, <em>Quaest. de elocut. Polyb.</em>, 1880, 277; Mlt. 87; B-D-F §64, 1; Mayser 303, com bibliografia adicional na nota 3; Rob. 689s.): <span class=\"greek\">ἑαυτούς = ἡμᾶς αὐτούς</span> (Themistocl., Ep. 15; Josefo, Bell. 5, 536; Justino, A I, 53, 3; D. 32, 5; 34, 1 e outros; Taciano 30, 1; Ath. 12, 1), 1Co 11:31. <span class=\"greek\">ἐν ἑαυτοῖς = ἐν ἡμῖν αὐτοῖς</span>, Rm 8:23; 2Co 1:9; = <span class=\"greek\">ἐν ὑμῖν αὐτοῖς</span>, Rm 11:25, variante (En 6:2, <span class=\"greek\">ἐκλεξώμεθα ἑαυτοῖς γυναῖκας</span>). <span class=\"greek\">δι’ ἑαυτῶν = δι’ ἡμῶν αὐ.</span>, 1Cl 32:4; <span class=\"greek\">παρ’ ἑαυτοῖς = παρ’ ὑμῖν αὐτοῖς</span>, Rm 11:25 (cf. Justino, D. 141, 1, e Taciano 11:2, <span class=\"greek\">δι’ ἑαυτούς</span>). <span class=\"greek\">ἑαυτοῖς = ὑμῖν αὐτοῖς</span> (cf. En 15:3; TestJob 45:3; TestDan 6:1; Josefo, Ant. 4, 190; 8, 277), Mt 23:31; Rm 11:25, variante; 1Cl 47:7. Essa substituição da primeira e segunda pessoas pela terceira é muito menos comum no singular (Ps.-Platão, Alc. 2, 143c; Díon Crisóstomo 30 [47], 6, <span class=\"greek\">σὺ … αὑτόν</span>; Eliano, VH 1, 21; Galeno, Protr. 10, p. 30, 10 John; Syntipas, p. 115, 10, <span class=\"greek\">μεθ’ ἑαυτοῦ</span>, «comigo»; TestJob 2:3, <span class=\"greek\">διελογιζόμην ἐν ἑαυτῷ</span>; GrBar 17:3, <span class=\"greek\">εἰς ἑαυτὸν ἐλθὼν δόξαν ἔφερον τῷ θεῷ</span>; inscrição da Transjordânia: NGG Phil.-Hist. Kl. Fachgr. V, nova série I/1, 1936, p. 3, 1; mais exemplos em Mlt. 87, n. 2; Mayser 304; Hauser 100), e dificilmente pode ser estabelecida com certeza para o NT em geral: ver Jo 18:34, variante; Rm 13:9, variante; cf. ISm 4:2 (variante <span class=\"greek\">ἐμαυτόν</span>); Hv 4, 1, 5 Joly (<span class=\"greek\">ἐμαυτῷ</span> B.); Hs 2:1.</p>\n<p><strong>② Marcador de relação recíproca, em lugar do pronome recíproco <span class=\"greek\">ἀλλήλων, ἀλλήλοις, ἀλλήλους</span>; «um ao outro, uns aos outros».</strong> (Também em autores anteriores, Kühner-G. I 573; papiros em Mayser 304; LXX; 4 [6] Esdr [POxy 1010], <span class=\"greek\">ἔδονται τὰ(ς) σάρκας αὐτῶν καὶ τὸ αἱμα αὐτῶν πίονται</span>; Taciano 3, 3. — W-S. §22, 13; B-D-F §287; Rob. 690.) <span class=\"greek\">συζητεῖν πρὸς ἑαυτούς</span>, Mc 9:16, variante (ver V. Taylor, comentário ao local; ASyn., aparato, com correção do aparato de Tdf.); <span class=\"greek\">λέγοντες πρὸς ἑαυτούς</span>, «enquanto diziam uns aos outros», Mc 10:26; cf. Jo 12:19 (<span class=\"greek\">πρὸς ἑ.</span> como Antig. Car. 39, <span class=\"greek\">μάχεσθαι πρὸς αὑτούς</span>; Luciano, Philops. 29; Ver. Hist. 1, 35; Taciano 26, 3, <span class=\"greek\">πολεμοῦντες … ἑαυτοῖς ἀλλήλους καθαιρεεῖτε</span>). <span class=\"greek\">χαρίζεσθαι ἑαυτοῖς</span>, «perdoar uns aos outros», Ef 4:32; Cl 3:13. <span class=\"greek\">νουθετεῖν ἑαυτούς</span>, «admoestar uns aos outros», Cl 3:16. <span class=\"greek\">εἰρηνεύειν ἐν ἑαυτοῖς</span>, «viver em paz uns com os outros», 1Ts 5:13; <span class=\"greek\">τὴν εἰς ἑαυτοὺς ἀγάπην</span>, 1Pe 4:9.</p>\n<p><strong>③ Marcador de posse pela pessoa de quem se fala ou que age, no lugar do pronome possessivo; «seu, sua».</strong> (Mayser 304s.; Mlt. 87s.) Mt 8:22; 21:8; 25:1; Lc 2:39; 9:60; 11:21; 12:36 e outras passagens. E. Schwartz, <em>Index lectionum</em>, 1905, 8s.; D. Tabachovitz, Eranos 93, 1955, 76ss.; A. Dihle, Noch einmal <span class=\"greek\">ἑαυτῷ</span>, Glotta 39, 1960, 83–92; ver Rydbeck (início de 1a). — DELG. M-M.</p></div></section></article> <article id=\"entry-eao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Imperfeito <span class=\"greek\">εἴων</span>; futuro <span class=\"greek\">ἐάσω</span>; primeiro aoristo <span class=\"greek\">εἴασα</span>; imperativo <span class=\"greek\">ἔασον</span>; optativo da terceira pessoa do singular <span class=\"greek\">ἐάσαι</span>, 1Cl 33:1; aoristo passivo, terceira pessoa do plural <span class=\"greek\">εἰάθησαν</span> (3Mc 5:18); infinitivo <span class=\"greek\">ἐαθῆναι</span>. Desde Homero.\n<p><strong>① Permitir que alguém faça algo; deixar, permitir.</strong> Com acusativo e infinitivo (Luciano, Dial. Mort. 13, 5; Taciano 12, 4): <span class=\"greek\">εἴασεν πάντα τὰ ἔθνη πορεύεσθαι</span>, «(Deus) deixou todas as nações seguir seu caminho», At 14:16; também 23:32; 27:32; 28:4; 1Cl 38:2; 53:3 (Êx 32:10); 55:4; Dg 9:1. Com negação, <span class=\"greek\">οὐκ ἐᾶν</span>, «não permitir, impedir» (Apiano, Bell. Civ. 5, 92, §384; PSI 380, 5 [249 a.C.]; 402, 11; 602, 10; Jó 9:18; 1Mc 12:40; 15:14; 2Mc 12:2), Mt 24:43; Lc 4:41 (com infinitivo presente, como em Polieno 7, 21, 5 e 6); 1Co 10:13; Mc 16:14, variante (manuscrito Freer, 3); 1Cl 33:1; IEph 3:2; 9:1; Hv 3, 1, 9; GJs 6:3. Com <span class=\"greek\">ἵνα</span> em vez do infinitivo: Hv 2, 3, 1. Com omissão do infinitivo (Sófocles, Ant. 538; POxy 1293, 21): <span class=\"greek\">οὐκ εἴασεν αὐτοὺς τὸ πνεῦμα Ἰησοῦ</span> (subentende-se <span class=\"greek\">πορευθῆναι</span>), «o Espírito de Jesus os impediu (de prosseguir)», At 16:7. <span class=\"greek\">οὐκ εἴων αὐτὸν … οἱ μαθηταί</span> (subentende-se <span class=\"greek\">εἰσελθεῖν</span>), «os discípulos não lhe permitiam (entrar)», At 19:30.</p>\n<p><strong>② Abster-se de incomodar, deter ou utilizar; deixar ir, deixar em paz.</strong> (Demóstenes 9, 26; Élio Aristides 34, 42 K. = 50, p. 562 D., <span class=\"greek\">ἐῶ τὰ ἄλλα</span>; PFay 122, 6; PTebt 319, 24; Josefo, C. Ap. 2, 118; GrBar 16:1; Justino, D. 85, 5; Ath. 6:1.) Com <span class=\"greek\">τί</span>, «algo»: <span class=\"greek\">τὴν στρεβλήν</span> (subentende-se <span class=\"greek\">ὁδόν</span>), «evitar o caminho tortuoso», Hm 6, 1, 2. Com pronome relativo como objeto: Hs 9, 2, 7. Equivalente a <span class=\"greek\">ἀφιέναι τινά</span>, «deixar alguém ir» (Máximo de Tiro 8, 5g; 6h), At 5:38, variante; Ap 2:20, texto recebido (leitura erasmiana? ver Tdf.); «deixar alguém entregue a si mesmo», Hv 2, 3, 1. Uso absoluto: <span class=\"greek\">ἐᾶτε ἕως τούτου</span>, «Parem! Basta disso!», Lc 22:51 (cf. Il. 21, 221, <span class=\"greek\">ἔασον</span>). <span class=\"greek\">ἔα δέ</span>, «deixando isso de lado; sem falar de; muito mais ou muito menos», 1Cl 39:5, mas ver também <span class=\"greek\">ἔα</span> (Jó 4:19, variante; 15:16; cf. P. Katz, JTS 47, 1946, 168s.).</p>\n<p><strong>③ Talvez termo técnico náutico:</strong> <span class=\"greek\">ἐᾶν τὰς ἀγκύρας εἰς τὴν θάλασσαν</span>, «deixar as âncoras no mar», At 27:40. — DELG. M-M.</p></div></section></article> <article id=\"entry-hebdomas-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑβδομάς, άδος, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hebdomás⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><strong>Semana.</strong> (Hipócrates, Aphorism. 2, 24; João Lido, Mens. 2, 4, p. 21 W. e outros; PPrinc III, 179, 16 [séculos V–VI d.C.]; LXX; ApcEsdr; Fílon; TestLevi 16:1; 17:10. Em Josefo, significa «sábado»: Bell. 2, 147 e 4, 99; C. Ap. 2, 175.) B 16:6 (citação de origem incerta; ver Windisch, Hdb., no local). — B. 1005. DELG, s.v. <span class=\"greek\">ἑπτά</span>. TW.</div></section></article> <article id=\"entry-hebdomekonta-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑβδομήκοντα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hebdomḗkonta⟧</span><span class=\"separator\">·</span><span>numeral cardinal indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Indeclinável (desde Heródoto). <strong>Setenta</strong>, Lc 10:1, variante textual; 10:17, variante (em <span class=\"greek\">οἱ ἑβδ.</span> deve ser subentendido algum substantivo, como em Plutarco, Mor. 345d; Josefo, Vi. 56b; 58); At 23:23. <span class=\"greek\">ἑ. δύο</span>, <strong>setenta e dois</strong> (TestAbr A 20, 3, p. 102, 24 [Stone p. 52], <span class=\"greek\">ἑβδομήκοντα δύο εἰσὶν θάνατοι</span>; EpArist 50, os 72 tradutores [outros exemplos dos pseudepígrafos em M. Philonenko, <em>JosAs</em>, p. 74]; Antig. Car. 111, os 72 filhos de Héracles; Plutarco, Mor. 356b, os 72 conspiradores associados a Tífon), Lc 10:1, 17 (B. Metzger, NTS 5, 1959, 299–306; S. Jellicoe, ibid. 6, 1960, 319–21). <span class=\"greek\">ἑ. πέντε</span>, <strong>setenta e cinco</strong>, At 7:14 (Demétrio: 722, frag. 1, 1s., Jac.). <span class=\"greek\">ἑ. ἕξ</span>, <strong>setenta e seis</strong>, At 27:37 (<span class=\"greek\">ἑ. ἑπτά</span>, «setenta e sete», ParJer 9:15; acerca do número de pessoas, ver Hemer, <em>Acts</em> 149). — DELG, s.v. <span class=\"greek\">ἑπτά</span>. M-M. TW.</div></section></article> <article id=\"entry-hebdomekontakis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑβδομηκοντάκις</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hebdomēkontákis⟧</span><span class=\"separator\">·</span><span>advérbio numeral</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\"><strong>Setenta vezes.</strong> <span class=\"greek\">ἑ. ἑπτά</span> pode ser abreviação de <span class=\"greek\">ἑ. ἑπτάκις</span>, «setenta vezes sete vezes» (cf. PGM 1, 143, <span class=\"greek\">ἑπτάκις ἑπτά</span>, «sete vezes sete»), mas é <strong>mais provável que signifique «setenta e sete vezes»</strong> (como em Gn 4:24; cf. TestBenj 7:4), Mt 18:22 (Mlt. 98, mas ver Mlt-H. 175; B-D-F §248, 2; Goodsp., <em>Probs.</em>, 29–31. Em Polieno 8, 33 e Plutarco, Mor. 245d, aparece o número 7777, designando uma multidão incalculável). — DELG, s.v. <span class=\"greek\">ἑπτά</span>. M-M. TW.</div></section></article> <article id=\"entry-hebdomos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕβδομος, η, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hébdomos⟧</span><span class=\"separator\">·</span><span>adjetivo numeral ordinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Homero e seguintes.) <strong>Sétimo</strong>, Jd 14; Ap 8:1; 10:7; 11:15; 16:17; 21:20; Hs 9, 1, 8; 9, 24, 1. Acerca da <strong>hora</strong> (Polieno 8, 16, 1, <span class=\"greek\">ὥρα ἑβ.</span>), Jo 4:52; do <strong>dia</strong>, At 21:27, códice D; Hb 4:4b; B 15:3 e 5 (três ocorrências de Gn 2:2); do <strong>mês</strong>, GJs 5:2 (de Strycker, em lugar de <span class=\"greek\">ἑπτά</span>; ver p. 206 de seu texto). <span class=\"greek\">ἡ ἑβδόμη</span> (subentende-se <span class=\"greek\">ἡμέρα</span>; cf. Antig. Car. 140; GDI 4705, 8 [Tera], <span class=\"greek\">ἐπάγεσθαι τὰν ἑβδόμαν</span>, acerca da celebração «do sétimo»; Br 1:2; Ez 30:20; Fílon, Vit. Cont. 30; 32; Justino, D. 24, 1), Hb 4:4a. <span class=\"greek\">ἐν τῷ ἑβδόμῳ</span>, «na sétima vez», 1Cl 56:8 (Jó 5:19). — DELG, s.v. <span class=\"greek\">ἑπτά</span>. M-M. TW.</div></section></article> <article id=\"entry-ebeblekei-ebebleto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐβεβλήκει, ἐβέβλητο</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ebeblḗkei, ebéblēto⟧</span><span class=\"separator\">·</span><span>formas verbais remissivas</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Ver <span class=\"greek\">βάλλω</span>.</div></section></article> <article id=\"entry-eber-name-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἔβερ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Éber⟧</span><span class=\"separator\">·</span><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Variante textual <span class=\"greek\">Ἕβερ</span>.) Nome próprio indeclinável, <strong>Éber, filho de Selá</strong> (Gn 10:24s.; em Josefo, <span class=\"greek\">Ἔβερος, ου</span> [Ant. 1, 147]), na genealogia de Jesus, Lc 3:35.</div></section></article> <article id=\"entry-eblethen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐβλήθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eblḗthēn⟧</span><span class=\"separator\">·</span><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">Ver <span class=\"greek\">βάλλω</span>.</div></section></article> <article id=\"entry-hebraikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑβραϊκός, ή, όν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Hebraïkós⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><div class=\"entry-text\">(Fílon; Josefo, Ant. 1, 5; PGM 4, 3085; cf. IDefixWünsch 1, 12; 15; Melitão, P. 1, 1; 94, 174.) <strong>Relativo ao povo hebreu; hebraico.</strong> <span class=\"greek\">γράμμασιν Ἑ.</span>, «com letras hebraicas» (EpArist 3; 30), o que pressupõe que a língua também fosse o hebraico (Josefo, Ant. 1, 5; 12, 48), Lc 23:38, variante textual; cf. <em>Kleine Texte</em> 8³, p. 9, 27 = ASyn. 297, 19. — TW. Sv.</div></section></article>"};
